export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-47\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 47,\n    \"title\": \"八說\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 10,\n    \"passageIds\": [\n      \"han-fei-zi_ch-47_p-1\",\n      \"han-fei-zi_ch-47_p-2\",\n      \"han-fei-zi_ch-47_p-3\",\n      \"han-fei-zi_ch-47_p-4\",\n      \"han-fei-zi_ch-47_p-5\",\n      \"han-fei-zi_ch-47_p-6\",\n      \"han-fei-zi_ch-47_p-7\",\n      \"han-fei-zi_ch-47_p-8\",\n      \"han-fei-zi_ch-47_p-9\",\n      \"han-fei-zi_ch-47_p-10\",\n      \"han-fei-zi_ch-47_p-11\",\n      \"han-fei-zi_ch-47_p-12\",\n      \"han-fei-zi_ch-47_p-13\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-47_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 1,\n      \"canonicalText\": \"為故人行私謂之不棄，以公財分施謂之仁人，輕祿重身謂之君子，枉法曲親謂之有行，棄官寵交謂之有俠，離世遁上謂之高傲，交爭逆令謂之剛材，行惠取眾謂之得民。不棄者吏有姦也，仁人者公財損也，君子者民難使也，有行者法制毀也，有俠者官職曠也，高傲者民不事也，剛材者令不行也，得民者君上孤也。此八者匹夫之私譽，人主之大敗也。反此八者，匹夫之私毀，人主之公利也。人主不察社稷之利害，而用匹夫之私譽，索國之無危亂，不可得矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-1_s-1\",\n        \"han-fei-zi_ch-47_p-1_s-2\",\n        \"han-fei-zi_ch-47_p-1_s-3\",\n        \"han-fei-zi_ch-47_p-1_s-4\",\n        \"han-fei-zi_ch-47_p-1_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"為所以人行私謂的不棄，以公財分施謂的仁人，輕祿重身謂的國君子，枉法規法令曲親謂的有行，棄官寵交謂的有俠，離世遁上謂的高傲，交爭逆令謂的剛材，行惠取眾謂的得民。不棄的人或事吏有姦啊，仁人的人或事公財損啊，國君子的人或事民難使啊，有行的人或事法規法令制毀啊，有俠的人或事官職曠啊，高傲的人或事民不事啊，剛材的人或事令不行啊，得民的人或事國君上孤啊。此八的人或事匹夫的私譽，人主的大敗啊。反此八的人或事，匹夫的私毀，人主的公利啊。人主不察社稷的利害，而且用匹夫的私譽，索國的無危亂，不可得矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「為故人行私謂之不棄，以公財分施謂之仁人，輕祿重身謂之君子，枉法曲親謂之有行，棄官寵交謂之有俠，離世遁上謂之高傲，交爭逆令謂之剛材，行惠取眾謂之得民」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「為」、「人」、「行」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「為故人行私謂之不棄以公財分施謂之仁人輕祿重身謂之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「不棄者吏有姦也，仁人者公財損也，君子者民難使也，有行者法制毀也，有俠者官職曠也，高傲者民不事也，剛材者令不行也，得民者君上孤也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 2,\n      \"canonicalText\": \"任人以事，存亡治亂之機也。無術以任人，無所任而不敗。人君之所任，非辯智則修潔也。任人者，使有勢也；智士者未必信也；為多其智，因惑其信也；以智士之計，處乘勢之資而為其私急，則君必欺焉。為智者之不可信也，故任修士；者，使斷事也，修士者未必智；為潔其身，因惑其智；以愚人之所惛，處治事之官而為其所然，則事必亂矣。故無術以用人，任智則君欺，任修則君事亂，此無術之患也。明君之道，賤德義貴，下必坐上，決誠以參，聽無門戶，故智者不得詐欺。計功而行賞，程能而授事，察端而觀失，有過者罪，有能者得，故愚者不任事。智者不敢欺，愚者不得斷，則事無失矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-2_s-1\",\n        \"han-fei-zi_ch-47_p-2_s-2\",\n        \"han-fei-zi_ch-47_p-2_s-3\",\n        \"han-fei-zi_ch-47_p-2_s-4\",\n        \"han-fei-zi_ch-47_p-2_s-5\",\n        \"han-fei-zi_ch-47_p-2_s-6\",\n        \"han-fei-zi_ch-47_p-2_s-7\",\n        \"han-fei-zi_ch-47_p-2_s-8\",\n        \"han-fei-zi_ch-47_p-2_s-9\",\n        \"han-fei-zi_ch-47_p-2_s-10\",\n        \"han-fei-zi_ch-47_p-2_s-11\",\n        \"han-fei-zi_ch-47_p-2_s-12\",\n        \"han-fei-zi_ch-47_p-2_s-13\",\n        \"han-fei-zi_ch-47_p-2_s-14\",\n        \"han-fei-zi_ch-47_p-2_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"任人以事，存亡治亂的機啊。無督察權術以任人，無所任而且不敗。人國君的所任，絕不是辯智則修潔啊。任人的人或事，使有權位威勢啊；智士的人或事未必信啊；為多他的智，因惑他的信啊；以智士的計，處乘權位威勢的資而且為他的私急，則國君必欺焉。為智的人或事的不可信啊，所以任修士；的人或事，使斷事啊，修士的人或事未必智；為潔他的身，因惑他的智；以愚人的所惛，處治事的官而且為他的所然，則事必亂矣。所以無督察權術以用人，任智則國君欺，任修則國君事亂，此無督察權術的患啊。明國君的道，賤德義貴，下必坐上，決誠以參，聽無門戶，所以智的人或事不得詐欺。計功而且行賞賜，程能而且授事，察端而且觀失，有過的人或事罪，有能的人或事得，所以愚的人或事不任事。智的人或事不敢欺，愚的人或事不得斷，則事無失矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「任人以事，存亡治亂之機也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「任」、「人」、「事」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「任人以事存亡治亂之機也無術以任人無所任而不敗人君」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「無術以任人，無所任而不敗」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 3,\n      \"canonicalText\": \"察士然後能知之，不可以為令，夫民不盡察。賢者然後能行之，不可以為法，夫民不盡賢。楊朱、墨翟，天下之所察也，幹世亂而卒不決，雖察而不可以為官職之令。鮑焦、華角，天下之所賢也，鮑焦木枯，華角赴河，雖賢不可以為耕戰之士。故人主之察，智士盡其辯焉；人主之所尊，能士盡其行焉。今世主察無用之辯，尊遠功之行，索國之富強，不可得也。博習辯智如孔、墨，孔、墨不耕耨，則國何得焉？修孝寡慾如曾、史，曾、史不戰攻，則國何利焉？匹夫有私便，人主有公利。不作而養足，不仕而名顯，此私便也。息文學而明法度，塞私便而一功勞，此公利也。錯法以道民也而又貴文學，則民之所師法也疑。賞功以勸民也而又尊行修，則民之產利也惰。夫貴文學以疑法，尊行修以貳功，索國之富強，不可得也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-3_s-1\",\n        \"han-fei-zi_ch-47_p-3_s-2\",\n        \"han-fei-zi_ch-47_p-3_s-3\",\n        \"han-fei-zi_ch-47_p-3_s-4\",\n        \"han-fei-zi_ch-47_p-3_s-5\",\n        \"han-fei-zi_ch-47_p-3_s-6\",\n        \"han-fei-zi_ch-47_p-3_s-7\",\n        \"han-fei-zi_ch-47_p-3_s-8\",\n        \"han-fei-zi_ch-47_p-3_s-9\",\n        \"han-fei-zi_ch-47_p-3_s-10\",\n        \"han-fei-zi_ch-47_p-3_s-11\",\n        \"han-fei-zi_ch-47_p-3_s-12\",\n        \"han-fei-zi_ch-47_p-3_s-13\",\n        \"han-fei-zi_ch-47_p-3_s-14\",\n        \"han-fei-zi_ch-47_p-3_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"察士然後能知的，不可以為令，夫民不盡察。賢的人或事然後能行的，不可以為法規法令，夫民不盡賢。楊朱、墨翟，天下的所察啊，幹世亂而且卒不決，雖察而且不可以為官職的令。鮑焦、華角，天下的所賢啊，鮑焦木枯，華角赴河，雖賢不可以為耕戰的士。所以人主的察，智士盡他的辯焉；人主的所尊，能士盡他的行焉。今世主察無用的辯，尊遠功的行，索國的富強，不可得啊。博習辯智如孔、墨，孔、墨不耕耨，則國何得焉？修孝寡慾如曾、史，曾、史不戰攻，則國何利焉？匹夫有私便，人主有公利。不作而且養足，不仕而且名顯，此私便啊。息文學而且明法規法令度，塞私便而且一功勞，此公利啊。錯法規法令以道民啊而且又貴文學，則民的所師法規法令啊疑。賞賜功以勸民啊而且又尊行修，則民的產利啊惰。夫貴文學以疑法規法令，尊行修以貳功，索國的富強，不可得啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「察士然後能知之，不可以為令，夫民不盡察」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「察」、「士」、「然」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「察士然後能知之不可以為令夫民不盡察賢者然後能行之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「賢者然後能行之，不可以為法，夫民不盡賢」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 4,\n      \"canonicalText\": \"搢笏干戚，不適有方鐵銛；登降周旋，不逮日中奏百；狸首射侯，不當強弩趨發；干城距衝，不若堙穴伏櫜。古人亟於德，中世逐於智，當今爭於力。古者寡事而備簡，樸陋而不盡，故有珧銚而推車者。古者人寡而相親，物多而輕利易讓，故有揖讓而傳天下者。然則行揖讓，高慈惠，而道仁厚，皆推政也。處多事之時，用寡事之器，非智者之備也；當大爭之世而循揖讓之軌，非聖人之治也。故智者不乘推車，聖人不行推政也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-4_s-1\",\n        \"han-fei-zi_ch-47_p-4_s-2\",\n        \"han-fei-zi_ch-47_p-4_s-3\",\n        \"han-fei-zi_ch-47_p-4_s-4\",\n        \"han-fei-zi_ch-47_p-4_s-5\",\n        \"han-fei-zi_ch-47_p-4_s-6\",\n        \"han-fei-zi_ch-47_p-4_s-7\",\n        \"han-fei-zi_ch-47_p-4_s-8\",\n        \"han-fei-zi_ch-47_p-4_s-9\",\n        \"han-fei-zi_ch-47_p-4_s-10\",\n        \"han-fei-zi_ch-47_p-4_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"搢笏干戚，不適有方鐵銛；登降周旋，不逮日中奏百；狸首射侯，不當強弩趨發；干城距衝，不若堙穴伏櫜。古人亟於德，中世逐於智，當今爭於力。古的人或事寡事而且備簡，樸陋而且不盡，所以有珧銚而且推車的人或事。古的人或事人寡而且相親，物多而且輕利易讓，所以有揖讓而且傳天下的人或事。然則行揖讓，高慈惠，而且道仁厚，皆推政啊。處多事的時，用寡事的器，絕不是智的人或事的備啊；當大爭的世而且循揖讓的軌，絕不是聖人的治啊。所以智的人或事不乘推車，聖人不行推政啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「搢笏干戚，不適有方鐵銛」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「搢」、「笏」、「干」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「搢笏干戚不適有方鐵銛登降周旋不逮日中奏百狸首射侯」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「登降周旋，不逮日中奏百」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 5,\n      \"canonicalText\": \"法所以制事，事所以名功也。法有立而有難，權其難而事成則立之；事成而有害，權其害而功多則為之。無難之法，無害之功，天下無有也。是以拔千丈之都，敗十萬之眾，死傷者軍之乘，甲兵折挫，士卒死傷，而賀戰勝得地者，出其小害計其大利也。夫沐者有棄髮，除者傷血肉，為人見其難，因釋其業，是無術之事也。先聖有言曰：「規有摩，而水有波，我欲更之，無奈之何！」此通權之言也。是以說有必立而曠於實者，言有辭拙而急於用者，故聖人不求無害之言，而務無易之事。人之不事衡石者，非貞廉而遠利也，石不能為人多少，衡不能為人輕重，求索不能得，故人不事也。明主之國，官不敢枉法，吏不敢為私，貨賂不行，是境內之事盡如衡石也。此其臣有姦者必知，知者必誅。是以有道之主，不求清潔之吏，而務必知之術也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-5_s-1\",\n        \"han-fei-zi_ch-47_p-5_s-2\",\n        \"han-fei-zi_ch-47_p-5_s-3\",\n        \"han-fei-zi_ch-47_p-5_s-4\",\n        \"han-fei-zi_ch-47_p-5_s-5\",\n        \"han-fei-zi_ch-47_p-5_s-6\",\n        \"han-fei-zi_ch-47_p-5_s-7\",\n        \"han-fei-zi_ch-47_p-5_s-8\",\n        \"han-fei-zi_ch-47_p-5_s-9\",\n        \"han-fei-zi_ch-47_p-5_s-10\",\n        \"han-fei-zi_ch-47_p-5_s-11\",\n        \"han-fei-zi_ch-47_p-5_s-12\",\n        \"han-fei-zi_ch-47_p-5_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"法規法令所以制事，事所以名功啊。法規法令有立而且有難，權他的難而且事成則立的；事成而且有害，權他的害而且功多則為的。無難的法規法令，無害的功，天下無有啊。是以拔千丈的都，敗十萬的眾，死傷的人或事軍的乘，甲兵折挫，士卒死傷，而且賀戰勝得地的人或事，出他的小害計他的大利啊。夫沐的人或事有棄髮，除的人或事傷血肉，為人見他的難，因釋他的業，是無督察權術的事啊。先聖有言說道：規有摩，而且水有波，我欲更的，無奈的何！此通權的言啊。是以說有必立而且曠於實的人或事，言有辭拙而且急於用的人或事，所以聖人不求無害的言，而且務無易的事。人的不事衡石的人或事，絕不是貞廉而且遠利啊，石不能為人多少，衡不能為人輕重，求索不能得，所以人不事啊。明主的國，官不敢枉法規法令，吏不敢為私，貨賂不行，是境內的事盡如衡石啊。此他的臣屬有姦的人或事必知，知的人或事必誅。是以有道的主，不求清潔的吏，而且務必知的督察權術啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「法所以制事，事所以名功也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「法」、「制」、「事」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「法所以制事事所以名功也法有立而有難權其難而事成則」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「法有立而有難，權其難而事成則立之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 6,\n      \"canonicalText\": \"慈母之於弱子也，愛不可為前。然而弱子有僻行，使之隨師；有惡病，使之事醫。不隨師則陷於刑，不事醫則疑於死。慈母雖愛，無益於振刑救死。則存子者非愛也，子母之性，愛也。臣主之權，筴也。母不能以愛存家，君安能以愛持國？明主者，通於富強則可以得欲矣。故謹於聽治，富強之法也。明其法禁，察其謀計。法明則內無變亂之患，計得則外無死虜之禍。故存國者，非仁義也。仁者，慈惠而輕財者也；暴者，心毅而易誅者也。慈惠則不忍，輕財則好與。心毅則憎心見於下，易誅則妄殺加於人。不忍則罰多宥赦，好與則賞多無功。憎心見則下怨其上，妄誅則民將背叛。故仁人在位，下肆而輕犯禁法，偷幸而望於上；暴人在位，則法令妄而臣主乖，民怨而亂心生。故曰：仁暴者，皆亡國者也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-6_s-1\",\n        \"han-fei-zi_ch-47_p-6_s-2\",\n        \"han-fei-zi_ch-47_p-6_s-3\",\n        \"han-fei-zi_ch-47_p-6_s-4\",\n        \"han-fei-zi_ch-47_p-6_s-5\",\n        \"han-fei-zi_ch-47_p-6_s-6\",\n        \"han-fei-zi_ch-47_p-6_s-7\",\n        \"han-fei-zi_ch-47_p-6_s-8\",\n        \"han-fei-zi_ch-47_p-6_s-9\",\n        \"han-fei-zi_ch-47_p-6_s-10\",\n        \"han-fei-zi_ch-47_p-6_s-11\",\n        \"han-fei-zi_ch-47_p-6_s-12\",\n        \"han-fei-zi_ch-47_p-6_s-13\",\n        \"han-fei-zi_ch-47_p-6_s-14\",\n        \"han-fei-zi_ch-47_p-6_s-15\",\n        \"han-fei-zi_ch-47_p-6_s-16\",\n        \"han-fei-zi_ch-47_p-6_s-17\",\n        \"han-fei-zi_ch-47_p-6_s-18\",\n        \"han-fei-zi_ch-47_p-6_s-19\",\n        \"han-fei-zi_ch-47_p-6_s-20\",\n        \"han-fei-zi_ch-47_p-6_s-21\",\n        \"han-fei-zi_ch-47_p-6_s-22\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"慈母的於弱子啊，愛不可為前。然而且弱子有僻行，使的隨師；有惡病，使的事醫。不隨師則陷於刑，不事醫則疑於死。慈母雖愛，無益於振刑救死。則存子的人或事絕不是愛啊，子母的性，愛啊。臣屬主的權，筴啊。母不能以愛存家，國君安能以愛持國？明主的人或事，通於富強則可以得欲矣。所以謹於聽治，富強的法規法令啊。明他的法規法令禁，察他的謀計。法規法令明則內無變亂的患，計得則外無死虜的禍。所以存國的人或事，絕不是仁義啊。仁的人或事，慈惠而且輕財的人或事啊；暴的人或事，心毅而且易誅的人或事啊。慈惠則不忍，輕財則好與。心毅則憎心見於下，易誅則妄殺加於人。不忍則刑罰多宥赦，好與則賞賜多無功。憎心見則下怨他的上，妄誅則民將背叛。所以仁人在位，下肆而且輕犯禁法規法令，偷幸而且望於上；暴人在位，則法規法令令妄而且臣屬主乖，民怨而且亂心生。因此韓絕不是子評論說道：仁暴的人或事，皆亡國的人或事啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「慈母之於弱子也，愛不可為前」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「慈」、「母」、「弱」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「慈母之於弱子也愛不可為前然而弱子有僻行使之隨師有」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「然而弱子有僻行，使之隨師」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 7,\n      \"canonicalText\": \"不能具美食而勸餓人飯，不為能活餓者也；不能闢草生粟而勸貸施賞賜，不能為富民者也。今學者之言也，不務本作而好末事，知道虛聖以說民，此勸飯之說。勸飯之說，明主不受也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-7_s-1\",\n        \"han-fei-zi_ch-47_p-7_s-2\",\n        \"han-fei-zi_ch-47_p-7_s-3\",\n        \"han-fei-zi_ch-47_p-7_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"不能具美食而且勸餓人飯，不為能活餓的人或事啊；不能闢草生粟而且勸貸施賞賜賜，不能為富民的人或事啊。今學的人或事的言啊，不務本作而且好末事，知道虛聖以說民，此勸飯的說。勸飯的說，明主不受啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「不能具美食而勸餓人飯，不為能活餓者也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「不」、「能」、「具」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「不能具美食而勸餓人飯不為能活餓者也不能闢草生粟而」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「不能闢草生粟而勸貸施賞賜，不能為富民者也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 8,\n      \"canonicalText\": \"書約而弟子辯，法省而民訟簡。是以聖人之書必著論，明主之法必詳事。盡思慮，揣得失，智者之所難也；無思無慮，挈前言而責後功，愚者之所易也。明主慮愚者之所易，以責智者之所難，故智慮力勞不用而國治也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-8_s-1\",\n        \"han-fei-zi_ch-47_p-8_s-2\",\n        \"han-fei-zi_ch-47_p-8_s-3\",\n        \"han-fei-zi_ch-47_p-8_s-4\",\n        \"han-fei-zi_ch-47_p-8_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"書約而且弟子辯，法規法令省而且民訟簡。是以聖人的書必著論，明主的法規法令必詳事。盡思慮，揣得失，智的人或事的所難啊；無思無慮，挈前言而且責後功，愚的人或事的所易啊。明主慮愚的人或事的所易，以責智的人或事的所難，所以智慮力勞不用而且國治啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「書約而弟子辯，法省而民訟簡」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「書」、「約」、「弟」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「書約而弟子辯法省而民訟簡是以聖人之書必著論明主之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「是以聖人之書必著論，明主之法必詳事」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 9,\n      \"canonicalText\": \"酸甘鹹淡，不以口斷而決於宰尹，則廚人輕君而重於宰尹矣。上下清濁，不以耳斷而決於樂正，則瞽工輕君而重於樂正矣。治國是非，不以術斷而決於寵人，則臣下輕君而重於寵人矣。人主不親觀聽，而制斷在下，託食於國者也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-9_s-1\",\n        \"han-fei-zi_ch-47_p-9_s-2\",\n        \"han-fei-zi_ch-47_p-9_s-3\",\n        \"han-fei-zi_ch-47_p-9_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"酸甘鹹淡，不以口斷而且決於宰尹，則廚人輕國君而且重於宰尹矣。上下清濁，不以耳斷而且決於樂正，則瞽工輕國君而且重於樂正矣。治國是絕不是，不以督察權術斷而且決於寵人，則臣屬下輕國君而且重於寵人矣。人主不親觀聽，而且制斷在下，託食於國的人或事啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「酸甘鹹淡，不以口斷而決於宰尹，則廚人輕君而重於宰尹矣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「酸」、「甘」、「鹹」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「酸甘鹹淡不以口斷而決於宰尹則廚人輕君而重於宰尹矣」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「上下清濁，不以耳斷而決於樂正，則瞽工輕君而重於樂正矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 10,\n      \"canonicalText\": \"使人不衣不食而不飢不寒，又不惡死，則無事上之意。意欲不宰於君，則不可使也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-10_s-1\",\n        \"han-fei-zi_ch-47_p-10_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"使人不衣不食而且不飢不寒，又不惡死，則無事上的意。意欲不宰於君主統治者，則不可使啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「使人不衣不食而不飢不寒，又不惡死，則無事上之意」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「使」、「人」、「不」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「使人不衣不食而不飢不寒又不惡死則無事上之意意欲不」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「意欲不宰於君，則不可使也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 11,\n      \"canonicalText\": \"今生殺之柄在大臣，而主令得行者，未嘗有也。虎豹必不用其爪牙而與鼷鼠同威，萬金之家、必不用其富厚而與監門同資。有土之君，說人不能利，惡人不能害，索人慾畏重己，不可得也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-11_s-1\",\n        \"han-fei-zi_ch-47_p-11_s-2\",\n        \"han-fei-zi_ch-47_p-11_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今生殺的柄在大臣屬，而且主令得行的人或事，未嘗有啊。虎豹必不用他的爪牙而且與鼷鼠同威，萬金的家、必不用他的富厚而且與監門同資。有土的國君，說人不能利，惡人不能害，索人慾畏重己，不可得啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「今生殺之柄在大臣，而主令得行者，未嘗有也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「生」、「殺」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今生殺之柄在大臣而主令得行者未嘗有也虎豹必不用其」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「虎豹必不用其爪牙而與鼷鼠同威，萬金之家、必不用其富厚而與監門同資」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-12\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 12,\n      \"canonicalText\": \"人臣肆意陳欲曰俠，人主肆意陳欲曰亂；人臣輕上曰驕，人主輕下曰暴。行理同實，下以受譽，上以得非，人臣大得，人主大亡。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-12_s-1\",\n        \"han-fei-zi_ch-47_p-12_s-2\",\n        \"han-fei-zi_ch-47_p-12_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"人臣屬肆意陳欲說道：俠，人主肆意陳欲說道：亂；人臣屬輕上說道：驕，人主輕下說道：暴。行理同實，下以受譽，上以得絕不是，人臣屬大得，人主大亡。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「人臣肆意陳欲曰俠，人主肆意陳欲曰亂」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「人」、「臣」、「肆」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「人臣肆意陳欲曰俠人主肆意陳欲曰亂人臣輕上曰驕人主」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「人臣輕上曰驕，人主輕下曰暴」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-13\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"order\": 13,\n      \"canonicalText\": \"明主之國，有貴臣無重臣。貴臣者，爵尊而官大也；重臣者，言聽而力多者也。明主之國，遷官襲級，官爵受功，故有貴臣。言不度行，而有偽必誅，故無重臣也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-47_p-13_s-1\",\n        \"han-fei-zi_ch-47_p-13_s-2\",\n        \"han-fei-zi_ch-47_p-13_s-3\",\n        \"han-fei-zi_ch-47_p-13_s-4\",\n        \"han-fei-zi_ch-47_p-13_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"明主的國，有貴臣屬無重臣屬。貴臣屬的人或事，爵尊而且官大啊；重臣屬的人或事，言聽而且力多的人或事啊。明主的國，遷官襲級，官爵受功，所以有貴臣屬。言不度行，而且有偽必誅，所以無重臣屬啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈八說〉。韓非深刻融合法、術、勢三大治國精要，此處「明主之國，有貴臣無重臣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「明」、「主」、「國」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「明主之國有貴臣無重臣貴臣者爵尊而官大也重臣者言聽」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「貴臣者，爵尊而官大也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-47_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"為故人行私謂之不棄，以公財分施謂之仁人，輕祿重身謂之君子，枉法曲親謂之有行，棄官寵交謂之有俠，離世遁上謂之高傲，交爭逆令謂之剛材，行惠取眾謂之得民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"不棄者吏有姦也，仁人者公財損也，君子者民難使也，有行者法制毀也，有俠者官職曠也，高傲者民不事也，剛材者令不行也，得民者君上孤也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"此八者匹夫之私譽，人主之大敗也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"反此八者，匹夫之私毀，人主之公利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-1_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"人主不察社稷之利害，而用匹夫之私譽，索國之無危亂，不可得矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"任人以事，存亡治亂之機也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"無術以任人，無所任而不敗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"人君之所任，非辯智則修潔也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"任人者，使有勢也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"智士者未必信也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"為多其智，因惑其信也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"以智士之計，處乘勢之資而為其私急，則君必欺焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"為智者之不可信也，故任修士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"者，使斷事也，修士者未必智；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 10,\n      \"canonicalText\": \"為潔其身，因惑其智；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 11,\n      \"canonicalText\": \"以愚人之所惛，處治事之官而為其所然，則事必亂矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 12,\n      \"canonicalText\": \"故無術以用人，任智則君欺，任修則君事亂，此無術之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 13,\n      \"canonicalText\": \"明君之道，賤德義貴，下必坐上，決誠以參，聽無門戶，故智者不得詐欺。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 14,\n      \"canonicalText\": \"計功而行賞，程能而授事，察端而觀失，有過者罪，有能者得，故愚者不任事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-2_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-2\",\n      \"order\": 15,\n      \"canonicalText\": \"智者不敢欺，愚者不得斷，則事無失矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"察士然後能知之，不可以為令，夫民不盡察。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"賢者然後能行之，不可以為法，夫民不盡賢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"楊朱、墨翟，天下之所察也，幹世亂而卒不決，雖察而不可以為官職之令。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"鮑焦、華角，天下之所賢也，鮑焦木枯，華角赴河，雖賢不可以為耕戰之士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"故人主之察，智士盡其辯焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"人主之所尊，能士盡其行焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"今世主察無用之辯，尊遠功之行，索國之富強，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"博習辯智如孔、墨，孔、墨不耕耨，則國何得焉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"修孝寡慾如曾、史，曾、史不戰攻，則國何利焉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"匹夫有私便，人主有公利。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 11,\n      \"canonicalText\": \"不作而養足，不仕而名顯，此私便也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 12,\n      \"canonicalText\": \"息文學而明法度，塞私便而一功勞，此公利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 13,\n      \"canonicalText\": \"錯法以道民也而又貴文學，則民之所師法也疑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 14,\n      \"canonicalText\": \"賞功以勸民也而又尊行修，則民之產利也惰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-3_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-3\",\n      \"order\": 15,\n      \"canonicalText\": \"夫貴文學以疑法，尊行修以貳功，索國之富強，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"搢笏干戚，不適有方鐵銛；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"登降周旋，不逮日中奏百；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"狸首射侯，不當強弩趨發；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"干城距衝，不若堙穴伏櫜。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"古人亟於德，中世逐於智，當今爭於力。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"古者寡事而備簡，樸陋而不盡，故有珧銚而推車者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"古者人寡而相親，物多而輕利易讓，故有揖讓而傳天下者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"然則行揖讓，高慈惠，而道仁厚，皆推政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"處多事之時，用寡事之器，非智者之備也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"當大爭之世而循揖讓之軌，非聖人之治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-4_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"故智者不乘推車，聖人不行推政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"法所以制事，事所以名功也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"法有立而有難，權其難而事成則立之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"事成而有害，權其害而功多則為之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"無難之法，無害之功，天下無有也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"是以拔千丈之都，敗十萬之眾，死傷者軍之乘，甲兵折挫，士卒死傷，而賀戰勝得地者，出其小害計其大利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"夫沐者有棄髮，除者傷血肉，為人見其難，因釋其業，是無術之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"先聖有言曰：「規有摩，而水有波，我欲更之，無奈之何！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"」此通權之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"是以說有必立而曠於實者，言有辭拙而急於用者，故聖人不求無害之言，而務無易之事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"人之不事衡石者，非貞廉而遠利也，石不能為人多少，衡不能為人輕重，求索不能得，故人不事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"明主之國，官不敢枉法，吏不敢為私，貨賂不行，是境內之事盡如衡石也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"此其臣有姦者必知，知者必誅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-5_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"是以有道之主，不求清潔之吏，而務必知之術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"慈母之於弱子也，愛不可為前。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"然而弱子有僻行，使之隨師；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"有惡病，使之事醫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"不隨師則陷於刑，不事醫則疑於死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"慈母雖愛，無益於振刑救死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"則存子者非愛也，子母之性，愛也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"臣主之權，筴也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"母不能以愛存家，君安能以愛持國？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"明主者，通於富強則可以得欲矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"故謹於聽治，富強之法也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"明其法禁，察其謀計。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"法明則內無變亂之患，計得則外無死虜之禍。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 13,\n      \"canonicalText\": \"故存國者，非仁義也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 14,\n      \"canonicalText\": \"仁者，慈惠而輕財者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 15,\n      \"canonicalText\": \"暴者，心毅而易誅者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 16,\n      \"canonicalText\": \"慈惠則不忍，輕財則好與。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 17,\n      \"canonicalText\": \"心毅則憎心見於下，易誅則妄殺加於人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 18,\n      \"canonicalText\": \"不忍則罰多宥赦，好與則賞多無功。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 19,\n      \"canonicalText\": \"憎心見則下怨其上，妄誅則民將背叛。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 20,\n      \"canonicalText\": \"故仁人在位，下肆而輕犯禁法，偷幸而望於上；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 21,\n      \"canonicalText\": \"暴人在位，則法令妄而臣主乖，民怨而亂心生。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-6_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-6\",\n      \"order\": 22,\n      \"canonicalText\": \"故曰：仁暴者，皆亡國者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"不能具美食而勸餓人飯，不為能活餓者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-7_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"不能闢草生粟而勸貸施賞賜，不能為富民者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-7_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"今學者之言也，不務本作而好末事，知道虛聖以說民，此勸飯之說。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-7_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"勸飯之說，明主不受也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"書約而弟子辯，法省而民訟簡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"是以聖人之書必著論，明主之法必詳事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"盡思慮，揣得失，智者之所難也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"無思無慮，挈前言而責後功，愚者之所易也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"明主慮愚者之所易，以責智者之所難，故智慮力勞不用而國治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"酸甘鹹淡，不以口斷而決於宰尹，則廚人輕君而重於宰尹矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"上下清濁，不以耳斷而決於樂正，則瞽工輕君而重於樂正矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"治國是非，不以術斷而決於寵人，則臣下輕君而重於寵人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-9_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"人主不親觀聽，而制斷在下，託食於國者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"使人不衣不食而不飢不寒，又不惡死，則無事上之意。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"意欲不宰於君，則不可使也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"今生殺之柄在大臣，而主令得行者，未嘗有也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"虎豹必不用其爪牙而與鼷鼠同威，萬金之家、必不用其富厚而與監門同資。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"有土之君，說人不能利，惡人不能害，索人慾畏重己，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-12_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"人臣肆意陳欲曰俠，人主肆意陳欲曰亂；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-12_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"人臣輕上曰驕，人主輕下曰暴。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-12_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"行理同實，下以受譽，上以得非，人臣大得，人主大亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-13_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"明主之國，有貴臣無重臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-13_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"貴臣者，爵尊而官大也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-13_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"重臣者，言聽而力多者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-13_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"明主之國，遷官襲級，官爵受功，故有貴臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-47_p-13_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-47\",\n      \"passageId\": \"han-fei-zi_ch-47_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"言不度行，而有偽必誅，故無重臣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
